// Command codegen_rec_policy captures a compile-time snapshot of the
// content-owned recommendation scoring policy resource as a generated Go
// file in runtime/recpolicy. The snapshot is the fail-safe Baseline used when no
// live policy file is configured or a hot-reload candidate fails validation.
//
// The generated file embeds the YAML verbatim. Runtime release identity is the
// Store semantic content digest; the source does not carry a manual version.
// Strong types, validation, and resolution live in hand-written recpolicy code.
package main

import (
	"flag"
	"fmt"
	"os"
	"path/filepath"
	"strconv"
)

func main() {
	var sourcePath, outDir string
	flag.StringVar(&sourcePath, "source", "services/content-service/resources/policies/content/post/recommendation_policy.yaml", "policy resource path")
	flag.StringVar(&outDir, "out-dir", "runtime/recpolicy", "Go output directory (recpolicy package)")
	flag.Parse()

	raw, err := os.ReadFile(sourcePath)
	must(err)

	content := fmt.Sprintf(`// Code generated by codegen_rec_policy. DO NOT EDIT.
// Source: services/content-service/resources/policies/content/post/recommendation_policy.yaml

package recpolicy

// baselinePolicyYAML is a compile-time snapshot of policy.yaml, used as the
// fail-safe baseline when no live policy file is configured or a hot-reload
// candidate fails validation. Single source: the metadata YAML referenced above.
const baselinePolicyYAML = %s
`, goStringLiteral(string(raw)))

	out := filepath.Join(outDir, "rec_policy_baseline.gen.go")
	must(os.WriteFile(out, []byte(content), 0o644))
	fmt.Printf("codegen_rec_policy: wrote %s\n", out)
}

// goStringLiteral renders s as a Go string literal, preferring a raw (backtick)
// literal for readability and falling back to a quoted literal if s contains a
// backtick (which a raw literal cannot represent).
func goStringLiteral(s string) string {
	for i := 0; i < len(s); i++ {
		if s[i] == '`' {
			return strconv.Quote(s)
		}
	}
	return "`" + s + "`"
}

func must(err error) {
	if err != nil {
		fail(err.Error())
	}
}

func fail(msg string) {
	fmt.Fprintln(os.Stderr, "codegen_rec_policy: "+msg)
	os.Exit(1)
}
